employee_amount:
// 全民健康保險法 §31: 2.11% on each bonus payment above four times the insured amount, capped at NT$10,000,000.
const facts = get(ctx.subject.employment, 'employee_extension_data.facts', {});
const bonus = get(ctx.subtotals, 'ADDITIONAL_WAGES', 0) - get(ctx.subtotals, 'ORDINARY_WAGES', 0);
const insured = Number(get(facts, 'statutory.NHI.elections.insured_amount', get(ctx.subtotals, 'ORDINARY_WAGES', 0)));
const excess = Math.max(0, bonus - ctx.lookup.bonus_salary_multiple * insured);
return round(Math.min(excess, ctx.lookup.payment_ceiling) * ctx.lookup.rate, 1, 'HALF_UP');

// 全民健康保險法 §31(1)(2): 2.11% on a salary payment to a worker insured elsewhere, charged whole from the minimum wage.
const facts = get(ctx.subject.employment, 'employee_extension_data.facts', {});
const exempt = get(facts, 'statutory.NHI_PART_TIME.elections.exempt', false) === true;
const elsewhere = get(facts, 'statutory.NHI.elections.insured_elsewhere', false) === true;
const payment = get(ctx.subtotals, 'ORDINARY_WAGES', 0);
return elsewhere && !exempt && payment >= ctx.lookup.part_time_payment_threshold
  ? round(Math.min(payment, ctx.lookup.payment_ceiling) * ctx.lookup.rate, 1, 'HALF_UP')
  : 0;

