employee_amount:
// 薪資所得扣繳辦法 §6–7: without a 免稅額申報表 the resident salary bears 5% of the whole month, withheld above NT$2,000; with one, annualise the month, deduct the exemptions and the standard and salary deductions, apply the 所得稅法 §5 ladder and withhold a twelfth.
const facts = get(ctx.subject.employment, 'employee_extension_data.facts', {});
const payDate = String(get(ctx.run, 'pay_date', ctx.run.salary_coverage.to));
const review = get(facts, 'statutory.INCOME_TAX.elections.tax_residency_reviews.' + payDate.substring(0, 4), null);
const resident = review !== null && get(review, 'resident_from', null) !== null && get(review, 'resident_from', '') <= payDate;
const wage = Math.max(0, get(ctx.subtotals, 'ORDINARY_WAGES', 0) - Number(get(ctx.statutory, 'LABOR_PENSION.employee', 0)));
const exemptions = get(facts, 'statutory.INCOME_TAX.elections.exemptions', null);
if (exemptions == null) {
  const flat = round(wage * ctx.lookup.rate, 1, 'DOWN');
  return resident && flat > ctx.lookup.minimum_withholding ? flat : 0;
}
const stepped = wage <= ctx.lookup.monthly_salary_rounding_threshold
  ? round(wage, ctx.lookup.monthly_salary_rounding_step, 'UP') - ctx.lookup.monthly_salary_rounding_step
  : wage;
const annual = 12 * stepped;
const deduction = ctx.lookup.annual_exemption_per_person * (1 + Math.max(0, Number(exemptions)))
  + ctx.lookup.annual_standard_deduction
  + Math.min(ctx.lookup.annual_salary_deduction, annual);
const scale = wage <= ctx.lookup.monthly_salary_rounding_threshold ? 10 : 1;
const tax = round(ladder(Math.max(0, annual - deduction), ctx.lookup.bands) / 12, scale, 'DOWN');
return resident && tax > ctx.lookup.minimum_withholding ? tax : 0;

// 各類所得扣繳率標準 §3(1): 18% of the reviewed non-resident's whole salary, or 6% at or below 1.5 times the minimum wage.
const facts = get(ctx.subject.employment, 'employee_extension_data.facts', {});
const payDate = String(get(ctx.run, 'pay_date', ctx.run.salary_coverage.to));
const review = get(facts, 'statutory.INCOME_TAX.elections.tax_residency_reviews.' + payDate.substring(0, 4), null);
const unreviewed = review === null || get(review, 'basis', '') !== 'NON_RESIDENT' || get(review, 'resident_from', null) !== null;
const wage = Math.max(0, get(ctx.subtotals, 'ADDITIONAL_WAGES', 0));
const rate = wage <= ctx.lookup.lower_rate_salary_ceiling ? ctx.lookup.lower_rate : ctx.lookup.rate;
return !unreviewed && wage > 0 ? round(wage * rate, 1, 'HALF_UP') : 0;

