const rate = Number(get(entity, 'pension_reserve_rate', ctx.lookup.default_rate_percent)) / 100;
return pension === 'LSA' || !pensionCovered ? round(wage * rate, 1, 'HALF_UP') : 0;

employee_amount:
// 薪資所得扣繳辦法 §7: 5% on a non-monthly bonus payment at or above the 起扣標準.
const facts = get(ctx.subject.employment, 'employee_extension_data.facts', {});
const payDate = String(get(ctx.run, 'pay_date', ctx.run.salary_coverage.to));
const review = get(facts, 'statutory.INCOME_TAX.elections.tax_residency_reviews.' + payDate.substring(0, 4), null);
const resident = review !== null && get(review, 'resident_from', null) !== null && get(review, 'resident_from', '') <= payDate;
const bonus = get(ctx.subtotals, 'ADDITIONAL_WAGES', 0) - get(ctx.subtotals, 'ORDINARY_WAGES', 0);
return resident && bonus >= ctx.lookup.bonus_withholding_threshold ? round(bonus * ctx.lookup.rate, 1, 'HALF_UP') : 0;

// 所得稅法 §14(1)(9) with 各類所得扣繳率標準 §2: 6% withheld on the exit pay above the per-service-year exemption; a tail under six months counts as half a year.
const pay = Math.max(0, get(ctx.subtotals, 'RETIREMENT', 0) - get(ctx.subtotals, 'ADDITIONAL_WAGES', 0));
const payDate = String(get(ctx.run, 'pay_date', ctx.run.salary_coverage.to));
const start = get(ctx.subject.employment, 'effective_range.from', ctx.run.salary_coverage.from);
const months = calendar_completed_months(start, payDate);
const years = Math.floor(months / 12) + (months % 12 === 0 ? 0 : months % 12 < 6 ? 0.5 : 1);
const exempt = ctx.lookup.exemption_per_service_year * years;
const facts = get(ctx.subject.employment, 'employee_extension_data.facts', {});
const review = get(facts, 'statutory.INCOME_TAX.elections.tax_residency_reviews.' + payDate.substring(0, 4), null);
const resident = review !== null && get(review, 'resident_from', null) !== null && get(review, 'resident_from', '') <= payDate;
return resident && pay > exempt ? round((pay - exempt) * ctx.lookup.rate, 1, 'HALF_UP') : 0;

// 職工福利金條例 §2(1)(3): 0.5% of the wage, deducted from the worker, where the entity has a welfare committee.
const entity = get(ctx.subject.employer, 'entity_extension_data', {});
const wage = Math.max(0, get(ctx.subtotals, 'ORDINARY_WAGES', 0));
return get(entity, 'welfare_committee_established', false) === true ? round(wage * ctx.lookup.employee_rate, 1, 'HALF_UP') : 0;

// 所得稅法 §14(1)(9) with 各類所得扣繳率標準 §2: 18% withheld on the exit pay above the per-service-year exemption; a tail under six months counts as half a year.
const pay = Math.max(0, get(ctx.subtotals, 'RETIREMENT', 0) - get(ctx.subtotals, 'ADDITIONAL_WAGES', 0));
const payDate = String(get(ctx.run, 'pay_date', ctx.run.salary_coverage.to));
const start = get(ctx.subject.employment, 'effective_range.from', ctx.run.salary_coverage.from);
const months = calendar_completed_months(start, payDate);
const years = Math.floor(months / 12) + (months % 12 === 0 ? 0 : months % 12 < 6 ? 0.5 : 1);
const exempt = ctx.lookup.exemption_per_service_year * years;
const facts = get(ctx.subject.employment, 'employee_extension_data.facts', {});
const review = get(facts, 'statutory.INCOME_TAX.elections.tax_residency_reviews.' + payDate.substring(0, 4), null);
const resident = review !== null && get(review, 'resident_from', null) !== null && get(review, 'resident_from', '') <= payDate;
return !resident && pay > exempt ? round((pay - exempt) * ctx.lookup.rate, 1, 'HALF_UP') : 0;
